const USTAWIENIA = { motywCiemny: true, jezyk: "pl" };

function zresetujMotyw(ustawienia) {
  ustawienia.motywCiemny = false; // CICHA modyfikacja - const NIE chroni przed tym
}

zresetujMotyw(USTAWIENIA);
console.log(USTAWIENIA.motywCiemny); // false - mimo ze USTAWIENIA to const!
// BLEDNE zalozenie: const NIE gwarantuje, ze obiekt pozostanie niezmieniony

const USTAWIENIA = Object.freeze({ motywCiemny: true, jezyk: "pl" });

function zresetujMotyw(ustawienia) {
  ustawienia.motywCiemny = false; // NIE dziala - obiekt jest zamrozony
}

zresetujMotyw(USTAWIENIA);
console.log(USTAWIENIA.motywCiemny); // true - nadal niezmienione

