zakupy.pop();
console.log(zakupy); // ['chleb', 'mleko']

// const przechowuje ADRES (referencje) obiektu/tablicy w pamieci, nie sama
// wartosc bezposrednio. Metody typu push()/pop() oraz modyfikacja wlasciwosci
// (obiekt.pole = ...) DZIALAJA POD TYM ADRESEM - modyfikuja to, na co adres
// wskazuje, ale sam adres (zawartosc zmiennej const) pozostaje niezmieniony.
// Przypisanie nowej wartosci do calej zmiennej (np. tablica = []) probowaloby
// PODMIENIC ten adres na inny - a wlasnie tego const zabrania.

const LANGUAGES = ["JavaScript", "Java", "Python"];
LANGUAGES.push("TypeScript");
console.log(LANGUAGES); // ['JavaScript', 'Java', 'Python', 'TypeScript']
// mozna, bo push() modyfikuje ZAWARTOSC istniejacej tablicy,
// nie probuje podmienic calej zmiennej LANGUAGES na inna tablice

